class Solution {
public:
    long long minimumRemoval(vector<int>& beans) {
        sort(beans.begin(),beans.end());
        long long total=accumulate(beans.begin(),beans.end(),0LL),ans=total;
        int n=beans.size();
        for(int i=0;i<n;++i) ans=min(ans,total-1LL*beans[i]*(n-i));
        return ans;
    }
};
